export function getPlatformCapability(
  platform: CapabilityPlatform,
  edge: CapabilityEdge,
  field: CapabilityField,
): CapabilityDeclaration {
  return PLATFORM_CAPABILITY_MAP[platform][field][edge];
}

export function getPlatformEdgeCapabilities(
  platform: CapabilityPlatform,
  edge: CapabilityEdge,
): ReadonlyArray<Readonly<{ field: CapabilityField; declaration: CapabilityDeclaration }>> {
  return CAPABILITY_FIELDS.map((field) => ({
    field,
    declaration: getPlatformCapability(platform, edge, field),
  }));
}
